<?php
session_start();require_once(__DIR__.'/../../../includes/auth/auth.php');require_once(__DIR__.'/../../../includes/db/db.php');require_once(__DIR__.'/../../../../utils/security/csrf/csrf.php');$pdo=get_db();$userId=(int)$_SESSION['user_id'];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!CSRF::validateToken(is_string($_POST['csrf_token']??null)?$_POST['csrf_token']:'') ){$error='Session expired. Reload this page and try again.';}else{$priority=$_POST['priority']??'medium';$type=trim((string)($_POST['issue_type']??''));$details=trim((string)($_POST['details']??''));if(!in_array($priority,['low','medium','high'],true)||$type===''||$details===''||mb_strlen($details)>4000){$error='Choose an issue type and enter details up to 4,000 characters.';}else{$admin=$pdo->query("SELECT id FROM users WHERE role='admin' AND status='active' ORDER BY id LIMIT 1")->fetchColumn();if(!$admin){$error='Support is temporarily unavailable.';}else{$q=$pdo->prepare('INSERT INTO messages (sender_id,receiver_id,content) VALUES (?,?,?)');$q->execute([$userId,(int)$admin,'Issue report ['.strtoupper($priority).'] '.$type.': '.$details]);$_SESSION['issue_sent']=true;header('Location: /lms-dashboard/More/Support/report-issue/report-issue.php');exit;}}}}$sent=!empty($_SESSION['issue_sent']);unset($_SESSION['issue_sent']);$q=$pdo->prepare("SELECT COUNT(*) FROM messages WHERE sender_id=? AND content LIKE 'Issue report [%'");$q->execute([$userId]);$issueCount=(int)$q->fetchColumn();$pageTitle='Report an issue';include(__DIR__.'/../../../includes/header/header.php');include(__DIR__.'/../../../includes/navbar/navbar.php');include(__DIR__.'/../../../includes/sidebar/sidebar.php');
?>
<main class="container py-5" style="max-width:1000px"><div class="mb-4"><span class="badge text-bg-danger-subtle text-danger">SUPPORT REQUEST</span><h1 class="fw-bold mt-2">Report an issue</h1><p class="text-muted">Describe what happened and our academy team will review it.</p></div><?php if($sent):?><div class="alert alert-success">Your issue report was sent to the support inbox.</div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><div class="row g-4"><div class="col-lg-8"><section class="card border-0 shadow-sm"><div class="card-body p-4"><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token,ENT_QUOTES,'UTF-8')?>"><div class="mb-3"><label class="form-label" for="issueType">Issue type</label><select class="form-select" id="issueType" name="issue_type" required><option value="">Choose an issue</option><option>Technical problem</option><option>Course access</option><option>Video playback</option><option>Payment question</option><option>Other</option></select></div><fieldset class="mb-3"><legend class="form-label">Priority</legend><div class="d-flex flex-wrap gap-3"><?php foreach(['low'=>'Low','medium'=>'Medium','high'=>'High'] as $key=>$label):?><label class="form-check"><input class="form-check-input" type="radio" name="priority" value="<?=$key?>" <?=$key==='medium'?'checked':''?>><span class="form-check-label"><?=$label?></span></label><?php endforeach;?></div></fieldset><div class="mb-4"><label class="form-label" for="issueDetails">What happened?</label><textarea class="form-control" id="issueDetails" name="details" rows="7" maxlength="4000" required></textarea></div><button class="btn btn-danger" type="submit"><i class="bi bi-flag me-1"></i>Send issue report</button></form></div></section></div><div class="col-lg-4"><section class="card border-0 shadow-sm"><div class="card-body p-4"><i class="bi bi-inbox fs-2 text-primary"></i><h2 class="h5 mt-3">Reports sent</h2><p class="display-6 fw-bold mb-0"><?=number_format($issueCount)?></p><p class="small text-muted">Issue reports from your account.</p><a href="/lms-dashboard/More/Support/faq/faq.php">Check common questions</a></div></section></div></div></main><?php include(__DIR__.'/../../../includes/footer/footer.php');?>
